/* Original Chinese onboarding content. Pure, engine-injected; no Vue, storage, DOM or network. */
export const CONTENT_VERSION = '2026-10-03.1';
export const SVG_FIGURES = {}; // Populated by the static illustration bundle below.
const cell = (q,r) => ({q,r});
const cr = (c,r) => cell(c-Math.floor(r/2),r);
const ship = shipId => ({kind:'ship',shipId});
const control = id => ({kind:'control',id});
const tile = (c,r) => ({kind:'cell',cell:cr(c,r)});
const all = (...conditions) => ({kind:'all',conditions});
const event = (types,fields={}) => ({kind:'event',types:Array.isArray(types)?types:[types],...fields});
const planMoves = (shipId,count) => ({kind:'planMoves',shipId,count});
const routeEnd = (shipId,c,r) => ({kind:'routeEnd',shipId,cell:cr(c,r)});
const atMove = (shipId,index,turn,forward) => ({kind:'moveAt',shipId,index,turn,forward});
const selected = shipId => ({kind:'selected',shipId});
const step = (id,title,instruction,hint,success,highlights,condition) => ({id,title,instruction,hint,success,highlights,condition});

